SELECT /* LGUTLC00130.retrieveMailTemplateMasterList */ mail_id , send_mail_name , system_code , module_code , sender_email_addr , mail_recipient_mgt_method_code , mail_recipient_mgt_method_code AS orgin_recp_method_code , 'Y' AS content_view , 'Y' AS recipient_view , use_flag FROM LGCOM_MAIL_M WHERE 1 = 1
AND system_code = #{systemCode}
AND module_code = #{moduleCode}
AND send_mail_name = #{sendMailName}
AND use_flag = #{useFlag}
ORDER BY mail_id

mapper.update:
UPDATE /* LGUTLC00130.updateMailTemplateMasterData */
       LGCOM_MAIL_M
   SET send_mail_name                 = #{sendMailName}
     , system_code                    = #{systemCode}
     , module_code                    = #{moduleCode}
     , sender_email_addr              = #{senderEmailAddr}
     , mail_recipient_mgt_method_code = #{mailRecipientMgtMethodCode}
     , use_flag                       = #{useFlag}
     , last_updated_by                = #{sessionUserId}
     , last_update_date               = SYSDATE
 WHERE mail_id                        = #{mailId}

mapper.delete:
DELETE FROM /* LGUTLC00130.deleteMailTemplateContentsData */
            LGCOM_MAIL_CONTENT_N
      WHERE mail_id       = #{mailId}
        AND language_code = #{languageCode}

mapper.update:
UPDATE /* LGUTLC00130.deleteMailTemplateContentsAttachFile */
       LGCOM_MAIL_CONTENT_N
   SET etc_attach_file_id = NULL
     , last_updated_by    = #{USER_SESSION.applicationUserId}
     , last_update_date   = SYSDATE
 WHERE mail_id            = #{mailId}
   AND language_code      = #{languageCode}

UPDATE /* LGUTLC00130.updateMailTemplateTextRecipientData */
       LGCOM_MAIL_RECIPIENT_N
   SET mail_type_code           = #{mailTypeCode}
     , last_updated_by          = #{sessionUserId}
     , last_update_date         = SYSDATE
 WHERE mail_id                  = #{mailId}
   AND mail_recipient_type_code = #{mailRecipientTypeCode}
   AND mail_recipient_addr      = #{mailRecipientAddr}

mapper.delete:
DELETE FROM /* LGUTLC00130.deleteMailTemplateTextRecipientData */
            LGCOM_MAIL_RECIPIENT_N
      WHERE mail_id                  = #{mailId}
        AND mail_recipient_type_code = #{mailRecipientTypeCode}
        AND mail_recipient_addr      = #{mailRecipientAddr}

DELETE FROM /* LGUTLC00130.deleteMailTemplateSqlRecipientData */
            LGCOM_MAIL_RECIPIENT_QUERY_N
      WHERE mail_id                  = #{mailId}
        AND mail_recipient_type_code = #{mailRecipientTypeCode}
        AND mail_seq_no              = #{mailSeqNo}
